class User(val name: String, age: Int) {        // 1. parameters bound
  val greeting = "Hello, $name"                // 2. initializer

  init {                                       // 3. init block
    require(age >= 0) { "age must be >= 0" }
  }

  var nickname: String = name.take(3)          // 4. next initializer

  constructor(name: String) : this(name, 0) {  // delegates, then runs
    nickname = "guest"                         // 5. last
  }
}

// ❌ The classic trap: an open member called during construction
open class Base {
  init { render() }                 // runs before Child's initializers
  open fun render() {}
}
class Child : Base() {
  private val title = "Hi"
  override fun render() = println(title.length)  // NPE — title is still null
}

