interface Repo {
  fun load(id: Long): User
  fun refresh()
  fun clear()
}

class LoggingRepo(private val inner: Repo) : Repo by inner {
  override fun load(id: Long): User {          // intercepted
    Log.d("Repo", "load($id)")
    return inner.load(id)
  }
  // refresh() and clear() are generated as inner.refresh() / inner.clear()
}

// Composition without a delegate reference of your own
class ObservableList<T>(
  private val backing: MutableList<T> = mutableListOf(),
) : MutableList<T> by backing {
  override fun add(element: T): Boolean {
    println("adding $element")
    return backing.add(element)
  }
}

// ❌ The surprise: inner's internal calls never reach your override
class Impl : Repo {
  override fun load(id: Long) = User(id)
  override fun refresh() { load(0) }   // calls Impl.load, not LoggingRepo.load
  override fun clear() {}
}

// A one-line test double over a real implementation
class FakeFailingRepo(real: Repo) : Repo by real {
  override fun refresh(): Unit = throw IOException("offline")
}

