// More than one method — anonymous object, and it may keep state
val listener = object : Animator.AnimatorListener {
  private var started = 0L
  override fun onAnimationStart(a: Animator) { started = now() }
  override fun onAnimationEnd(a: Animator) { report(now() - started) }
  override fun onAnimationCancel(a: Animator) {}
  override fun onAnimationRepeat(a: Animator) {}
}

@JvmInline
value class Money(val cents: Long) : Comparable<Money> {
  operator fun plus(other: Money) = Money(cents + other.cents)
  operator fun times(factor: Int) = Money(cents * factor)
  operator fun unaryMinus() = Money(-cents)
  override fun compareTo(other: Money) = cents.compareTo(other.cents)
}

val total = Money(1000) + Money(250) * 2
val cheaper = Money(500) < total          // uses compareTo

class Grid(private val cells: MutableMap<Pair<Int, Int>, Char> = mutableMapOf()) {
  operator fun get(x: Int, y: Int): Char = cells[x to y] ?: '.'
  operator fun set(x: Int, y: Int, value: Char) { cells[x to y] = value }
  operator fun contains(c: Char) = c in cells.values
}

val grid = Grid()
grid[1, 2] = 'X'
if ('X' in grid) println(grid[1, 2])

